import './CriteriaFilterPanelStyle.css';
import React, { useState } from 'react';

const CriteriaFilterPanel = ({ criteria, setCriteria, onUpdateSearch }) => {
  const handleCheckboxChange = (e) => {
    const { name, checked } = e.target;
    setCriteria((prev) => ({
      ...prev,
      [name]: checked ? prev[name] || { min: 0, max: 0 } : null,
    }));
  };

  const handleRangeChange = (e, type, attr) => {
    const value = parseFloat(e.target.value);
    setCriteria((prev) => ({
      ...prev,
      [attr]: {
        ...prev[attr],
        [type]: value,
      },
    }));
  };

  return (
<div className="filter-panel">
  <h3>Advanced Search Criteria</h3>

  <div>
    <label>
      <input
        type="checkbox"
        name="genre"
        checked={!!criteria.genre}
        onChange={handleCheckboxChange}
      />
      Genre
    </label>
    {criteria.genre !== null && (
      <input
        type="text"
        name="genre"
        value={criteria.genre}
        onChange={handleRangeChange}
        placeholder="Enter genre"
      />
    )}
  </div>

  {['tempo', 'danceability', 'energy', 'valence', 'acousticness', 'instrumentalness', 'liveness'].map((attr) => (
    <div key={attr}>
      <label>
        <input
          type="checkbox"
          name={`min_${attr}`}
          checked={criteria[`min_${attr}`] !== null}
          onChange={handleCheckboxChange}
        />
        {attr.charAt(0).toUpperCase() + attr.slice(1)}
      </label>
      {criteria[`min_${attr}`] !== null && (
        <>
          <div className="range-label">
            <span>Min</span><span>Max</span>
          </div>
          <input
            type="range"
            name={`min_${attr}`}
            value={criteria[`min_${attr}`] || 0}
            onChange={handleRangeChange}
            min="0"
            max="1"
            step="0.1"
          />
          <input
            type="range"
            name={`max_${attr}`}
            value={criteria[`max_${attr}`] || 1}
            onChange={handleRangeChange}
            min="0"
            max="1"
            step="0.1"
          />
        </>
      )}
    </div>
  ))}

  <button onClick={onUpdateSearch}>Update Search</button>
</div>
  );
};

export default CriteriaFilterPanel;
